class Graph:
    def __init__(self):
        self.nodes = {}
        self.edges = {}

    def add_node(self, n):
        self.nodes[n] = []

    def add_edge(self, a, b, weight=1):
        if a in self.nodes and b in self.nodes:
            self.nodes[a].append((b, weight))
            self.nodes[b].append((a, weight))

    def nodes(self):
        return list(self.nodes.keys())

    def neighbors(self, a):
        return sorted(self.nodes.get(a, []), key=lambda x: x[0])

    def bfs(self, start):
        if start not in self.nodes:
            raise KeyError(f"Node {start} not found")

        visited = set()
        queue = [start]
        result = []

        while queue:
            current = queue.pop(0)
            if current not in visited:
                visited.add(current)
                result.append(current)
                queue.extend([neighbor for neighbor, _ in self.neighbors(current) if neighbor not in visited])

        return result

