class Graph:
    def __init__(self):
        self.nodes = set()
        self.edges = defaultdict(list)

    def add_node(self, n):
        self.nodes.add(n)

    def add_edge(self, a, b, weight=1):
        self.edges[a].append((b, weight))

    def nodes(self):
        return self.nodes

    def neighbors(self, a):
        return self.edges[a]

    def has_cycle(self):
        visited = set()
        rec_stack = set()

        def dfs(node):
            if node in rec_stack:
                return True
            if node in visited:
                return False

            visited.add(node)
            rec_stack.add(node)

            for neighbor, _ in self.neighbors(node):
                if dfs(neighbor):
                    return True

            rec_stack.remove(node)
            return False

        for node in self.nodes:
            if dfs(node):
                return True

        return False

